    public static VoxelShape pillar(int tier, int section) { return PILLARS[tier-1][section]; }
    private static VoxelShape shape(double[][] boxes) {
        VoxelShape value = Shapes.empty();
        for (double[] b : boxes) value = Shapes.or(value, Block.box(b[0], b[1], b[2], b[3], b[4], b[5]));
        return value.optimize();
    }
